//! The SMILES reader against RDKit: the 20 study cases, extra aromatic/charged/isotopic/stereo cases and the 625 rows of composti.csv,
//! all from `tests/data/golden.json` (generated by `tools/struttura_dato/confronto.py --golden`; no RDKit needed here).

use mzlab_mol::{GroupKind, Mol, Status, Stereo};
use serde_json::{json, Value};
use std::collections::BTreeMap;

fn golden() -> Value {
    serde_json::from_str(include_str!("data/golden.json")).expect("golden.json")
}

/// The record as JSON, restricted to what the reader asserts: stereo elements that are `defined`.
fn defined(rec: &Value) -> Vec<Value> {
    rec["stereo"]
        .as_array()
        .expect("stereo")
        .iter()
        .filter(|s| s["status"] == "defined")
        .cloned()
        .collect()
}

fn bonds_of(rec: &Value) -> BTreeMap<(u64, u64), u64> {
    rec["bonds"]
        .as_array()
        .expect("bonds")
        .iter()
        .map(|b| {
            (
                (b["a"].as_u64().unwrap_or(0), b["b"].as_u64().unwrap_or(0)),
                b["o"].as_u64().unwrap_or(0),
            )
        })
        .collect()
}

/// Same bond pairs; the same orders, except between the aromatic bonds where more than one Kekulé form is right (then the per-atom sums must agree).
fn same_bonds(mine: &Value, truth: &Value, aromatic: &Value, what: &str) {
    let (a, b) = (bonds_of(mine), bonds_of(truth));
    assert_eq!(
        a.keys().collect::<Vec<_>>(),
        b.keys().collect::<Vec<_>>(),
        "{what}: bond pairs"
    );
    let arom: Vec<(u64, u64)> = aromatic
        .as_array()
        .expect("aromatic")
        .iter()
        .map(|p| (p[0].as_u64().unwrap_or(0), p[1].as_u64().unwrap_or(0)))
        .collect();
    for (k, o) in &a {
        assert!(
            *o == b[k] || arom.contains(k),
            "{what}: bond {k:?} order {o} against {}",
            b[k]
        );
    }
    let sums = |m: &BTreeMap<(u64, u64), u64>| {
        let mut s = BTreeMap::new();
        for (&(x, y), &o) in m {
            *s.entry(x).or_insert(0) += o;
            *s.entry(y).or_insert(0) += o;
        }
        s
    };
    assert_eq!(sums(&a), sums(&b), "{what}: bond order sum per atom");
}

fn groups_json(m: &Mol) -> Vec<Value> {
    let mut g: Vec<Value> = m
        .groups
        .iter()
        .map(|g| serde_json::to_value(g).expect("group"))
        .collect();
    g.sort_by_key(|v| v["atoms"].to_string());
    g
}

fn check(input: &str, rec: &Value, aromatic: &Value) {
    let m = Mol::from_smiles(input).unwrap_or_else(|e| panic!("{input}: {e}"));
    let mine: Value = serde_json::to_value(&m).expect("json");
    assert_eq!(mine["atoms"], rec["atoms"], "{input}: atoms");
    same_bonds(&mine, rec, aromatic, input);
    assert_eq!(defined(&mine), defined(rec), "{input}: defined stereo");
    let mut truth: Vec<Value> = rec["groups"].as_array().expect("groups").clone();
    truth.sort_by_key(|v| v["atoms"].to_string());
    assert_eq!(groups_json(&m), truth, "{input}: stereo groups");
}

#[test]
fn the_twenty_cases_read_like_rdkit() {
    let g = golden();
    for c in g["cases"].as_array().expect("cases") {
        check(
            c["input"].as_str().unwrap_or_default(),
            &c["records"]["input_order"],
            &c["aromatic"],
        );
    }
}

#[test]
fn extra_cases_read_like_rdkit() {
    let g = golden();
    let cases = g["smiles_cases"].as_array().expect("smiles_cases");
    assert!(cases.len() > 60);
    for c in cases {
        check(
            c["input"].as_str().unwrap_or_default(),
            &c["record"],
            &c["aromatic"],
        );
    }
}

/// Splits one CSV line with quoted fields.
fn fields(line: &str) -> Vec<String> {
    let (mut out, mut cur, mut quoted) = (Vec::new(), String::new(), false);
    for ch in line.chars() {
        match ch {
            '"' => quoted = !quoted,
            ',' if !quoted => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out
}

/// First 16 hex digits of the SHA-256 of the compact JSON of `v` in the field order of the record (as the golden data computes it).
fn digest<T: serde::Serialize>(v: &T) -> String {
    use sha2::{Digest, Sha256};
    let text = serde_json::to_string(v).expect("json");
    mzlab_mol::hex(&Sha256::digest(text.as_bytes()))[..16].to_string()
}

#[test]
fn composti_csv_reads_without_loss() {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../TP_Mine/data/composti.csv"
    ))
    .expect("composti.csv");
    let truth = golden();
    let truth = truth["composti"].as_array().expect("composti");
    let rows: Vec<Vec<String>> = text
        .lines()
        .skip(1)
        .filter(|l| !l.is_empty())
        .map(fields)
        .collect();
    assert_eq!(rows.len(), 625);
    assert_eq!(truth.len(), 625);
    let (mut with_stereo, mut with_unspecified) = (0, 0);
    let mut stereo_read = 0;
    for (row, t) in rows.iter().zip(truth) {
        let smiles = &row[3];
        let m = Mol::from_smiles(smiles).unwrap_or_else(|e| panic!("{smiles}: {e}"));
        assert_eq!(
            digest(&m.atoms),
            t[0].as_str().unwrap_or_default(),
            "{smiles}: atoms"
        );
        assert_eq!(
            m.bonds.len() as u64,
            t[1].as_u64().unwrap_or(0),
            "{smiles}: bonds"
        );
        assert_eq!(
            digest(&m.stereo),
            t[2].as_str().unwrap_or_default(),
            "{smiles}: defined stereo"
        );
        with_stereo += usize::from(t[3].as_u64().unwrap_or(0) > 0);
        with_unspecified += usize::from(t[4].as_u64().unwrap_or(0) > 0);
        stereo_read += usize::from(!m.stereo.is_empty());
    }
    // the study's figures, from the RDKit side of the golden data; the reader finds every specified element and claims no unknown one
    assert_eq!((with_stereo, with_unspecified), (286, 111));
    assert!(stereo_read > 0 && stereo_read <= with_stereo);
}

#[test]
fn a_smiles_never_creates_unknown_elements() {
    let m = Mol::from_smiles("CC(O)C(=O)O").expect("lactic acid, centre not marked");
    assert!(
        m.stereo.is_empty(),
        "an unmarked centre is not asserted either way by the reader"
    );
    let m = Mol::from_smiles("C[C@H](O)C(=O)O |&1:1|").expect("racemic lactic acid");
    assert_eq!(m.groups.len(), 1);
    assert_eq!(m.groups[0].kind, GroupKind::And);
    assert!(m.stereo.iter().all(|s| matches!(
        s,
        Stereo::Tetra {
            status: Status::Defined,
            ..
        }
    )));
    assert_eq!(json!(m.groups[0].atoms), json!([1]));
}

#[test]
fn rejects_what_it_cannot_read() {
    for bad in [
        "",
        "C(",
        "C)",
        "C1CC",
        "C11",
        "[C@TH1H](F)(Cl)Br",
        "C[Xx]",
        "C=",
        "CC |&1:0|",
        "[CH3",
        "C%1",
    ] {
        assert!(Mol::from_smiles(bad).is_err(), "{bad:?} should fail");
    }
}

/// The record with its groups in a fixed order, as the JSON of its core.
fn normal(m: &Mol) -> String {
    let mut m = m.clone();
    m.groups.sort_by(|a, b| a.atoms.cmp(&b.atoms));
    m.core_json()
}

/// Writes `m`, reads the text back and checks that it is the same molecule in the order of the text; writing the result again gives the same text.
fn roundtrip(m: &Mol, what: &str) {
    let (text, order) = m
        .to_smiles_with_order()
        .unwrap_or_else(|e| panic!("{what}: {e}"));
    let back = Mol::from_smiles(&text).unwrap_or_else(|e| panic!("{what}: {text}: {e}"));
    let mut new_of_old = vec![0u32; order.len()];
    for (k, &old) in order.iter().enumerate() {
        new_of_old[old as usize] = k as u32;
    }
    let moved = m.renumbered(&new_of_old).expect("permutation");
    assert_eq!(normal(&moved), normal(&back), "{what}: {text}");
    assert_eq!(
        back.to_smiles().expect("again"),
        text,
        "{what}: writing is stable"
    );
}

/// A smiles cannot say "unknown": drop those elements before comparing.
fn writable(rec: &Value) -> Mol {
    let mut m = Mol::from_json(&rec.to_string()).expect("record");
    m.stereo.retain(|s| {
        matches!(
            s,
            Stereo::Tetra {
                status: Status::Defined,
                ..
            } | Stereo::Db {
                status: Status::Defined,
                ..
            }
        )
    });
    m
}

#[test]
fn golden_records_survive_write_and_read() {
    let g = golden();
    for c in g["cases"].as_array().expect("cases") {
        roundtrip(
            &writable(&c["records"]["input_order"]),
            c["name"].as_str().unwrap_or_default(),
        );
    }
    for c in g["smiles_cases"].as_array().expect("smiles_cases") {
        roundtrip(
            &writable(&c["record"]),
            c["input"].as_str().unwrap_or_default(),
        );
    }
}

#[test]
fn composti_survive_write_and_read() {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../TP_Mine/data/composti.csv"
    ))
    .expect("composti.csv");
    for line in text.lines().skip(1).filter(|l| !l.is_empty()) {
        let smiles = &fields(line)[3];
        roundtrip(&Mol::from_smiles(smiles).expect("reads"), smiles);
    }
}

#[test]
fn written_text_is_plain_and_exact() {
    let ala = Mol::from_smiles("C[C@H](N)C(=O)O").expect("L-alanine");
    assert_eq!(
        ala.to_smiles().expect("writes"),
        "[CH3][C@H]([NH2])[C](=[O])[OH]"
    );
    // both marks point the same way: the fluorines are trans
    let e = Mol::from_smiles("F/C=C/F").expect("E");
    assert_eq!(e.to_smiles().expect("writes"), "[F]\\[CH]=[CH]\\[F]");
    let rac = Mol::from_smiles("C[C@H](O)CC |&1:1|").expect("racemic");
    assert_eq!(
        rac.to_smiles().expect("writes"),
        "[CH3][C@H]([OH])[CH2][CH3] |&1:1|"
    );
}

#[test]
fn explicit_hydrogens_stay_atoms() {
    let m = Mol::from_smiles("[H][C@](F)(Cl)Br").expect("explicit H");
    assert_eq!(m.atoms.len(), 5);
    match &m.stereo[0] {
        Stereo::Tetra {
            refs, implicit_h, ..
        } => {
            assert_eq!(refs.as_deref(), Some(&[0u32, 2, 3, 4][..]));
            assert_eq!(*implicit_h, Some(false));
        }
        s => panic!("{s:?}"),
    }
    let implicit = Mol::from_smiles("[C@H](F)(Cl)Br").expect("implicit H");
    assert_ne!(m.core_hash_hex(), implicit.core_hash_hex());
}

#[test]
fn unmarked_stereo_is_not_asserted() {
    // RDKit lists the double bond of CC=CC as an unknown element; the reader only writes what the text marks
    let g = golden();
    let butene = g["cases"]
        .as_array()
        .expect("cases")
        .iter()
        .find(|c| c["name"] == "butene_unspec")
        .expect("case");
    assert_eq!(
        butene["records"]["input_order"]["stereo"][0]["status"],
        "unknown"
    );
    assert!(Mol::from_smiles("CC=CC").expect("reads").stereo.is_empty());
}
